// Removing uploaded media is an immediate, durable action. Other editor changes
// remain drafts until Save artwork; removal is serialized before any manual save.
function removeArtworkAndPersist(kind){
 const characterId=activeId, originalDraft=ART.normalize(ui.artworkDraft);
 const title=kind==='portrait'?'Portrait':'Custom emblem';
 const stripped=kind==='portrait'?{portrait:'',tokenImage:''}:{emblem:'',emblemPreset:'book',tokenImage:''};
 ui.artworkDraft={...originalDraft,...stripped};
 render();
 const status=document.getElementById('artwork-status');
 if(status)status.textContent='Removing '+title.toLowerCase()+' and saving on this device…';
 artworkRemovalPending=artworkRemovalPending.then(async()=>{
  const originalLibrary=library;
  const current=originalLibrary?.characters.find(c=>c.id===characterId);
  if(!current)throw Error('Character no longer exists.');
  const persistedDraft={...ART.normalize(current.artwork),...stripped};
  const updatedArtwork={...persistedDraft,tokenImage:await AU.tokenImage(persistedDraft)};
  library=L.setArtwork(library,characterId,updatedArtwork);
  if(!(await saveLibrary())){library=originalLibrary;throw Error('The updated artwork could not be saved.');}
  if(characterId===activeId&&ui.tab==='artwork'){
   const message=document.getElementById('artwork-status');
   if(message)message.textContent=title+' removed and saved. Other changes still need Save artwork.';
  }
  return true;
 }).catch(error=>{
  if(characterId===activeId&&ui.tab==='artwork'){
   const restored=ART.normalize(library?.characters.find(c=>c.id===activeId)?.artwork);
   if(kind==='portrait')ui.artworkDraft={...ui.artworkDraft,portrait:restored.portrait};
   else ui.artworkDraft={...ui.artworkDraft,emblem:restored.emblem,emblemPreset:restored.emblemPreset};
   render();
   const message=document.getElementById('artwork-status');
   if(message)message.textContent='Removal was not saved: '+error.message;
  }
  return false;
 });
}
// Save artwork and its rendered token together. The explicit "Use as sheet icon"
// action uses this same durable path, so clicking it cannot leave the old emblem
// visible because a separate Save button was forgotten.
function saveArtworkDraft(useTokenAsSheetIcon=false){
 if(ui.artworkBusy||!ui.artworkDraft)return;
 if(useTokenAsSheetIcon)ui.artworkDraft={...ART.normalize(ui.artworkDraft),sheetIcon:'token'};
 ui.artworkBusy=true;
 for(const button of document.querySelectorAll('[data-action="artwork-save"],[data-action="artwork-use-token-as-sheet"]'))button.disabled=true;
 const status=document.getElementById('artwork-status');
 if(status)status.textContent=useTokenAsSheetIcon?'Saving the token as your character-sheet icon…':'Preparing and saving your character artwork…';
 const characterId=activeId;
 (async()=>{
  try{
   if(!(await artworkRemovalPending))throw Error('A previous removal could not be saved. Please try again.');
   const draft=ART.normalize(ui.artworkDraft),tokenImage=await AU.tokenImage(draft);
   if(useTokenAsSheetIcon&&!tokenImage)throw Error('The framed token could not be created. Please choose artwork and try again.');
   const candidate={...draft,tokenImage};
   if(characterId!==activeId)throw Error('The active character changed while saving.');
   const before=library;library=L.setArtwork(library,activeId,candidate);
   if(!(await saveLibrary())){library=before;throw Error('Could not save artwork. Export a backup and check storage capacity.');}
   ui.artworkDraft=null;ui.tab='sheet';
   ui.notice=useTokenAsSheetIcon?'Framed token saved as your character-sheet icon':'Character artwork saved locally · Included in backups';
   render(false);
  }catch(error){
   const message=document.getElementById('artwork-status');if(message)message.textContent=error.message;
   for(const button of document.querySelectorAll('[data-action="artwork-save"],[data-action="artwork-use-token-as-sheet"]'))button.disabled=false;
  }finally{ui.artworkBusy=false;}
 })();
}
