 if(grid&&ui.layoutMode&&drag.pending){const before=FL.fromDOM(grid),dest=drag.pending;const oldCol=before.findIndex(c=>c.includes(drag.key)),oldIdx=before[oldCol]?.indexOf(drag.key)??-1;const targetIdx=dest.column===oldCol&&oldIdx<dest.index?dest.index-1:dest.index;ui.layoutDraft=FL.move(before,drag.key,dest.column,targetIdx);applySheetColumns(ui.layoutDraft);refreshLayoutButtons();layoutAnnounce(FL.LABELS[drag.key]+' placed. Choose Save layout to keep the arrangement.');}else layoutAnnounce('No changes made.');
