 ui.hpAmount=String(amount);const type=ui.damageType||'Unspecified',relentlessAllowed=stack.present.character.templateKind==='starter'&&stack.present.character.build?.characterClass==='Barbarian'&&stack.present.character.level>=11&&stack.present.resources.classState?.raging&&document.getElementById('damage-relentless')?.checked===true,options={...(relentlessAllowed?{relentlessRoll:DICE.rollDie(20)}:{}),undyingSentinel:!!document.getElementById('damage-undying')?.checked,orcEndurance:!!document.getElementById('damage-orc-endurance')?.checked,featLastStand:!!document.getElementById('damage-feat-last-stand')?.checked,heavyArmorAttack:!!document.getElementById('damage-heavy-armor-attack')?.checked,resistant:ui.damageResistance,vulnerable:ui.damageVulnerability,immune:ui.damageImmunity,spellDamage:!!document.getElementById('wizard-spell-damage')?.checked,defense:ui.damageDefense||'none',...(ui.damageDefense==='deflect-attacks'?{deflectDie:DICE.rollDie(10)}:{})};
