document.addEventListener('pointermove',event=>{
 if(!sheetDrag||event.pointerId!==sheetDrag.pointerId||!ui.layoutMode)return;
 event.preventDefault();const grid=sheetGrid();if(!grid)return;
 const target=document.elementFromPoint(event.clientX,event.clientY)?.closest('.folio-panel[data-layout-id],.sheet-left,.sheet-middle,.sheet-right');
 grid.querySelectorAll('.layout-drop-target,.layout-insert-before,.layout-insert-after').forEach(el=>el.classList.remove('layout-drop-target','layout-insert-before','layout-insert-after'));
 sheetDrag.pending=null;if(!target||!grid.contains(target)||target===sheetDrag.panel)return;
 const column=target.matches('.folio-panel')?target.parentElement:target;
 const columns=[...grid.children].filter(c=>c.matches('.sheet-left,.sheet-middle,.sheet-right'));
 const colIndex=columns.indexOf(column);if(colIndex<0)return;
 if(target.matches('.folio-panel[data-layout-id]')){
   const center=target.getBoundingClientRect().top+target.getBoundingClientRect().height/2;
   const after=event.clientY>=center;
   const panels=[...column.children].filter(c=>c.matches('.folio-panel[data-layout-id]'));
   const idx=panels.indexOf(target)+(after?1:0);
   sheetDrag.pending={column:colIndex,index:idx};target.classList.add(after?'layout-insert-after':'layout-insert-before');
 }else{const panels=[...column.children].filter(c=>c.matches('.folio-panel[data-layout-id]'));
   sheetDrag.pending={column:colIndex,index:panels.length};column.classList.add('layout-drop-target');}
});
